 */


void insertBefore(Bucket bucket){
  this.next=bucket;
  if (bucket != null) {
    this.prev=bucket.prev;
    if (bucket.prev != null) {
      bucket.prev.next=this;
    }
    bucket.prev=this;
  }
 else {
    this.prev=null;
  }
}


