    /**
     * 基于十六进制的字符转换
     * @version : 2013-8-13
     * @author 赵永春 (zyc@hasor.net)
     */
    public static abstract class HexConversion {
        /** 字符串转换成十六进制字符串 */
        public static String str2HexStr(final String str) {
            char[] chars = "0123456789ABCDEF".toCharArray();
            StringBuilder sb = new StringBuilder("");
            byte[] bs = str.getBytes();
            int bit;
            for (byte element : bs) {
                bit = (element & 0x0f0) >> 4;
                sb.append(chars[bit]);
                bit = element & 0x0f;
                sb.append(chars[bit]);
            }
            return sb.toString();
        }

        /** 十六进制转换字符串 */
        public static String hexStr2Str(final String hexStr) {
            String str = "0123456789ABCDEF";
            char[] hexs = hexStr.toCharArray();
            byte[] bytes = new byte[hexStr.length() / 2];
            int n;
            for (int i = 0; i < bytes.length; i++) {
                n = str.indexOf(hexs[2 * i]) * 16;
                n += str.indexOf(hexs[2 * i + 1]);
                bytes[i] = (byte) (n & 0xff);
            }
            return new String(bytes);
        }

        /** bytes转换成十六进制字符串 */
        public static String byte2HexStr(final byte[] b) {
            String hs = "";
            String stmp = "";
            for (byte element : b) {
                stmp = Integer.toHexString(element & 0XFF);
                if (stmp.length() == 1) {
                    hs = hs + "0" + stmp;
                } else {
                    hs = hs + stmp;
                    //if (n<b.length-1) hs=hs+":";
                }
            }
            return hs.toUpperCase();
        }

        /** bytes转换成十六进制字符串 */
        public static byte[] hexStr2Bytes(final String src) {
            int m = 0, n = 0;
            int l = src.length() / 2;
            //System.out.println(l);
            byte[] ret = new byte[l];
            for (int i = 0; i < l; i++) {
                m = i * 2 + 1;
                n = m + 1;
                ret[i] = HexConversion.uniteBytes(src.substring(i * 2, m), src.substring(m, n));
            }
            return ret;
        }

        /** String的字符串转换成unicode的String */
        public static String stringToUnicode(final String strText) throws Exception {
            char c;
            String strRet = "";
            int intAsc;
            String strHex;
            for (int i = 0; i < strText.length(); i++) {
                c = strText.charAt(i);
                intAsc = c;
                strHex = Integer.toHexString(intAsc);
                if (intAsc > 128) {
                    strRet += "\\u" + strHex;
                } else {
                    // 低位在前面补00
                    strRet += "\\u00" + strHex;
                }
            }
            return strRet;
        }

        /** unicode的String转换成String的字符串 */
        public static String unicodeToString(final String hex) {
            int t = hex.length() / 6;
            StringBuilder str = new StringBuilder();
            for (int i = 0; i < t; i++) {
                String s = hex.substring(i * 6, (i + 1) * 6);
                // 高位需要补上00再转
                String s1 = s.substring(2, 4) + "00";
                // 低位直接转
                String s2 = s.substring(4);
                // 将16进制的string转为int
                int n = Integer.valueOf(s1, 16) + Integer.valueOf(s2, 16);
                // 将int转换为字符
                char[] chars = Character.toChars(n);
                str.append(new String(chars));
            }
            return str.toString();
        }

        private static byte uniteBytes(final String src0, final String src1) {
            byte b0 = Byte.decode("0x" + src0).byteValue();
            b0 = (byte) (b0 << 4);
            byte b1 = Byte.decode("0x" + src1).byteValue();
            byte ret = (byte) (b0 | b1);
            return ret;
        }
    }
}

